def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    last_opponent_move = history[-1][1]
    if last_opponent_move == 'C':
        return 'C'
    else:
        consecutive_defections = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                consecutive_defections += 1
            else:
                break
        if consecutive_defections >= 3:
            if rng.random() < 0.1:
                return 'C'
        elif consecutive_defections == 2:
            if rng.random() < 0.2:
                return 'C'
        return 'D'
